 * Translate DDL column constraints into engine specific
 * constriant clauses.
 *
 * @param array $constraint
 * array(
 *  'not null' => BOOL,
 *  'unique' => BOOL,
 *  'primary key' => BOOL,
 * )
 *
 * @return string
 */
function _db_map_column_constraints($constraints) {
  $elements = array();
  if (array_key_exists('not null', $constraints) && $constraints['not null']) {
